   306→			fmt.Printf("[%s] Will continue but sync may fail\n", time.Now().Format(time.RFC3339))
   307→		}
   308→	}
   309→
   310→	// Initial sync
   311→	if err := InitialSync(ctx, workspaceDir, client); err != nil {
   312→		fmt.Fprintf(os.Stderr, "Initial sync failed: %v\n", err)
   313→		os.Exit(1)
   314→	}
   315→
   316→	// Start watching
